import{_ as o,o as r,c as e,a2 as s}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"快速上手指南 (Quick Start Guide)","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":null}'),d={name:"getting-started.md"};function a(n,t,i,l,c,g){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="快速上手指南-quick-start-guide" tabindex="-1">快速上手指南 (Quick Start Guide) <a class="header-anchor" href="#快速上手指南-quick-start-guide" aria-label="Permalink to &quot;快速上手指南 (Quick Start Guide)&quot;">​</a></h1><p>歡迎使用 <strong>Craft-Core Hosting 容器託管平台</strong>。本指南將協助您完成帳號登入、建立第一台 Docker 機器，並開通網頁存取。</p><hr><h2 id="_1-帳號登入" tabindex="-1">1. 帳號登入 <a class="header-anchor" href="#_1-帳號登入" aria-label="Permalink to &quot;1. 帳號登入&quot;">​</a></h2><p>Craft-Core Hosting 採用 Discord 安全驗證：</p><ol><li>點擊登入頁面的 <strong>「使用 Discord 帳號登入 / 免費開始使用」</strong>。</li><li>授權登入後即可直接進入控制台管理您的 Docker 機器與工作區。</li></ol><hr><h2 id="_2-建立第一台-docker-託管機器" tabindex="-1">2. 建立第一台 Docker 託管機器 <a class="header-anchor" href="#_2-建立第一台-docker-託管機器" aria-label="Permalink to &quot;2. 建立第一台 Docker 託管機器&quot;">​</a></h2><p>在儀表板點擊 <strong>「+ 建立新託管機器」</strong> 按鈕，填寫以下參數：</p><table tabindex="0"><thead><tr><th>欄位名稱</th><th>說明與規範</th><th>範例</th></tr></thead><tbody><tr><td><strong>專案名稱</strong></td><td>容器識別名稱 (僅限小寫英數與 dash)</td><td><code>discord-bot-service</code></td></tr><tr><td><strong>執行環境 (Runtime)</strong></td><td>支援 <code>Node.js 22 (LTS)</code> 或 <code>Python 3.11</code></td><td><code>Node.js 22 (LTS)</code></td></tr><tr><td><strong>部署來源</strong></td><td>可選擇 <strong>GitHub Repo URL</strong> 或上傳 <strong>ZIP 部署包</strong></td><td><code>https://github.com/user/repo</code></td></tr><tr><td><strong>啟動指令 (CMD)</strong></td><td>容器啟動時執行的命令</td><td><code>node index.js</code> 或 <code>python main.py</code></td></tr><tr><td><strong>內部 Port</strong></td><td>應用程式在容器內監聽的連接埠</td><td><code>3000</code></td></tr><tr><td><strong>CPU / RAM 配額</strong></td><td>調整該容器分配到的 CPU 比例與記憶體上限</td><td><code>50% CPU / 512MB RAM</code></td></tr></tbody></table><hr><h2 id="_3-個人資源限制規範" tabindex="-1">3. 個人資源限制規範 <a class="header-anchor" href="#_3-個人資源限制規範" aria-label="Permalink to &quot;3. 個人資源限制規範&quot;">​</a></h2><p>為確保容器隔離與穩定性，平台實施資源配額管理：</p><ul><li><strong>機器數量上限</strong>：每位用戶最多可建立 <strong>2 台</strong> Docker 機器。</li><li><strong>CPU 配額總和</strong>：所有機器加總不可超過 <strong>100% CPU</strong>。</li><li><strong>記憶體限額總和</strong>：所有機器加總不可超過 <strong>1024 MB (1GB RAM)</strong>。</li><li><strong>硬碟空間限額總和</strong>：所有機器加總不可超過 <strong>4096 MB (4GB Disk)</strong>。</li></ul><hr><h2 id="_4-自動核發對外-port-與-8-位專屬-ssl-域名" tabindex="-1">4. 自動核發對外 Port 與 8 位專屬 SSL 域名 <a class="header-anchor" href="#_4-自動核發對外-port-與-8-位專屬-ssl-域名" aria-label="Permalink to &quot;4. 自動核發對外 Port 與 8 位專屬 SSL 域名&quot;">​</a></h2><p>若您的機器需要對外提供 HTTP API 或網頁服務：</p><ol><li>在機器專案「設定」頁面中點擊 <strong>「自動開啟對外 Port」</strong>。</li><li><strong>無需管理員審核</strong>，系統將秒級自動配發 8 位隨機英數專屬子域名與對外 Port：<div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://app-a8k2m9x1.hosting.craft-core.xyz</span></span></code></pre></div></li><li>您可以隨時點擊 <strong>「刪除 Port」</strong> 釋放資源，或點擊 <strong>「重新核發 Port 與域名」</strong> 替換全新的 8 位專屬域名。</li></ol>',18)])])}const u=o(d,[["render",a]]);export{p as __pageData,u as default};
